def test_options_link_style_reference() -> None:
    """Links use reference-style formatting."""
    html = "<p><a href='https://example.com'>Example</a> and <a href='https://other.com'>Other</a></p>"
    options = ConversionOptions(link_style=LinkStyle("Reference"))

    result = convert(html, options)
    assert result.content is not None
    assert "Example" in result.content
    assert result.content is not None
    assert "Other" in result.content
    assert result.content is not None
    assert "example.com" in result.content


def test_options_list_custom_bullets() -> None:
    """Custom bullet character for unordered lists."""
    html = "<ul><li>Item A</li><li>Item B</li></ul>"
    options = ConversionOptions(bullets="*")

    result = convert(html, options)
    assert result.content is not None
    assert "* Item A" in result.content
    assert result.content is not None
    assert "* Item B" in result.content


def test_options_list_indent_tabs() -> None:
    """Tab indentation type for nested list items."""
    html = "<ul><li>Parent<ul><li>Child</li></ul></li></ul>"
    options = ConversionOptions(list_indent_type=ListIndentType("Tabs"))

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Parent" in result.content
    assert result.content is not None
    assert "Child" in result.content


def test_options_list_indent_width_four() -> None:
    """Nested lists indented with 4 spaces per level."""
    html = "<ul><li>Outer<ul><li>Inner</li></ul></li></ul>"
    options = ConversionOptions(list_indent_width=4)

    result = convert(html, options)
    assert result.content is not None
    assert "Outer" in result.content
    assert result.content is not None
    assert "Inner" in result.content


def test_options_max_depth_default_unlimited() -> None:
    """Default max_depth (null) converts deeply nested content fully."""
    html = "<div><div><div><div><p>Deep content</p></div></div></div></div>"

    result = convert(html)
    assert result.content is not None
    assert "Deep content" in result.content


def test_options_max_depth_truncates() -> None:
    """max_depth truncates content beyond the specified depth."""
    html = "<div><p>Shallow</p><div><div><div><p>Too deep</p></div></div></div></div>"
    options = ConversionOptions(max_depth=3)

    result = convert(html, options)
    assert result.content is not None
    assert "Shallow" in result.content
    assert result.content is None or "Too deep" not in result.content


def test_options_max_depth_zero_empty() -> None:
    """max_depth of 0 produces empty output."""
    html = "<p>Hello</p>"
    options = ConversionOptions(max_depth=0)

    result = convert(html, options)
    assert result.content == ""


def test_options_max_image_size_generous_limit() -> None:
    """A generous max_image_size accommodates a small data-URI image without warnings."""
    html = '<p>Image: <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg==" alt="pixel"></p>'
    options = ConversionOptions(extract_images=True, max_image_size=10485760)

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Image" in result.content


def test_options_max_image_size_tiny_limit_safe() -> None:
    """A tiny max_image_size does not crash conversion even when the image exceeds the limit."""
    html = '<p>Tiny limit: <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg==" alt="pixel"></p>'
    options = ConversionOptions(extract_images=True, max_image_size=10)

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Tiny limit" in result.content


def test_options_newline_backslash() -> None:
    """Hard line breaks rendered with backslash."""
    html = "<p>Line one<br>Line two</p>"
    options = ConversionOptions(newline_style=NewlineStyle("Backslash"))

    result = convert(html, options)
    assert result.content is not None
    assert "Line one" in result.content
    assert result.content is not None
    assert "Line two" in result.content


def test_options_newline_spaces() -> None:
    """Hard line breaks rendered with trailing spaces."""
    html = "<p>First<br>Second</p>"
    options = ConversionOptions(newline_style=NewlineStyle("Spaces"))

    result = convert(html, options)
    assert result.content is not None
    assert "First" in result.content
