def test_options_output_format_djot() -> None:
    """Djot output format produces djot-compatible markup."""
    html = "<p>Simple paragraph.</p>"
    options = ConversionOptions(output_format=OutputFormat("Djot"))

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Simple paragraph." in result.content


def test_options_output_format_markdown() -> None:
    """Default markdown output format produces standard markdown."""
    html = "<h1>Title</h1><p>Some text.</p>"
    options = ConversionOptions(heading_style=HeadingStyle("Atx"), output_format=OutputFormat("Markdown"))

    result = convert(html, options)
    assert result.content is not None
    assert "# Title" in result.content
    assert result.content is not None
    assert "Some text." in result.content


def test_options_output_format_plain() -> None:
    """Plain text output format strips markdown syntax."""
    html = "<h1>Title</h1><p>Some <strong>bold</strong> text.</p>"
    options = ConversionOptions(output_format=OutputFormat("Plain"))

    result = convert(html, options)
    assert result.content is not None
    assert "Title" in result.content
    assert result.content is not None
    assert "bold" in result.content
    assert result.content is not None
    assert "text." in result.content
    assert result.content is None or "**bold**" not in result.content
    assert result.content is None or "# Title" not in result.content


def test_options_preprocessing_aggressive() -> None:
    """Aggressive preset removes nav, footer, aside unconditionally."""
    html = "<nav>Menu</nav><article><h1>Title</h1><p>Content</p></article><aside>Sidebar</aside><footer>Footer</footer>"
    options = ConversionOptions(preprocessing=PreprocessingOptions(preset=PreprocessingPreset("Aggressive")))

    result = convert(html, options)
    assert result.content is not None
    assert "Title" in result.content
    assert result.content is not None
    assert "Content" in result.content
    assert result.content is None or "Menu" not in result.content


def test_options_preprocessing_enabled_false_skips_cleanup() -> None:
    """Disabling preprocessing entirely preserves elements the standard preset would remove."""
    html = "<nav>NavSection</nav><p>Paragraph</p>"
    options = ConversionOptions(preprocessing=PreprocessingOptions(enabled=False))

    result = convert(html, options)
    assert result.content is not None
    assert "NavSection" in result.content
    assert result.content is not None
    assert "Paragraph" in result.content


def test_options_preprocessing_minimal() -> None:
    """Minimal preset preserves nav, footer, aside."""
    html = "<nav>Navigation</nav><p>Content</p><footer>Footer</footer>"
    options = ConversionOptions(preprocessing=PreprocessingOptions(preset=PreprocessingPreset("Minimal")))

    result = convert(html, options)
    assert result.content is not None
    assert "Navigation" in result.content
    assert result.content is not None
    assert "Content" in result.content
    assert result.content is not None
    assert "Footer" in result.content


def test_options_preprocessing_remove_forms() -> None:
    """Forms are removed when remove_forms is true."""
    html = "<p>Before</p><form><input type='text'/><button>Submit</button></form><p>After</p>"
    options = ConversionOptions(preprocessing=PreprocessingOptions(remove_forms=True))

    result = convert(html, options)
    assert result.content is not None
    assert "Before" in result.content
    assert result.content is not None
    assert "After" in result.content
    assert result.content is None or "Submit" not in result.content


def test_options_preprocessing_remove_navigation_false_keeps_nav() -> None:
    """Setting remove_navigation to false preserves nav and aside elements."""
    html = "<nav>SiteMenu</nav><main><p>MainContent</p></main><aside>SidebarText</aside>"
    options = ConversionOptions(preprocessing=PreprocessingOptions(remove_navigation=False))

    result = convert(html, options)
    assert result.content is not None
    assert "SiteMenu" in result.content
    assert result.content is not None
    assert "MainContent" in result.content
    assert result.content is not None
    assert "SidebarText" in result.content


def test_options_preserve_tags_iframe() -> None:
    """Iframe tags preserved as raw HTML in output."""
    html = "<p>Before</p><iframe src='video.html' width='560'></iframe><p>After</p>"
    options = ConversionOptions(preserve_tags=["iframe"])

    result = convert(html, options)
    assert result.content is not None
    assert "Before" in result.content
    assert result.content is not None
    assert "After" in result.content
    assert result.content is not None
    assert "<iframe" in result.content


def test_options_skip_images_true() -> None:
    """Images are omitted from output when skipImages is true."""
    html = "<p>Before <img src='test.jpg' alt='photo'> After</p>"
    options = ConversionOptions(skip_images=True)

    result = convert(html, options)
    assert result.content is not None
    assert "Before" in result.content
    assert result.content is not None
    assert "After" in result.content
    assert result.content is None or "photo" not in result.content


def test_options_strip_newlines() -> None:
    """Strip newlines produces single-line paragraphs."""
    html = "<p>First paragraph.</p><p>Second paragraph.</p>"
