def test_options_url_escape_style_angle_default() -> None:
    """Default angle style wraps URLs containing spaces in angle brackets."""
    html = '<a href="/file (1).pdf">file</a>'
    options = ConversionOptions(url_escape_style=UrlEscapeStyle("Angle"))

    result = convert(html, options)
    assert result.content is not None
    assert "</file (1).pdf>" in result.content


def test_options_url_escape_style_percent_angle_brackets_in_url() -> None:
    """Percent style encodes angle brackets in link URLs from issue 392."""
    html = '<a href="/file (1) <draft>.pdf">file</a>'
    options = ConversionOptions(url_escape_style=UrlEscapeStyle("Percent"))

    result = convert(html, options)
    assert result.content is not None
    assert "/file%20%281%29%20%3Cdraft%3E.pdf" in result.content


def test_options_url_escape_style_percent_image() -> None:
    """Percent style encodes special characters in image src URLs."""
    html = '<img src="/img (1) <draft>.png" alt="alt">'
    options = ConversionOptions(url_escape_style=UrlEscapeStyle("Percent"))

    result = convert(html, options)
    assert result.content is not None
    assert "/img%20%281%29%20%3Cdraft%3E.png" in result.content


def test_options_url_escape_style_percent_link() -> None:
    """Percent style encodes spaces and parens in link URLs."""
    html = '<a href="/file (1).pdf">file</a>'
    options = ConversionOptions(url_escape_style=UrlEscapeStyle("Percent"))

    result = convert(html, options)
    assert result.content is not None
    assert "/file%20%281%29.pdf" in result.content
    assert result.content is None or "</" not in result.content


def test_options_whitespace_normalized() -> None:
    """Normalized whitespace mode collapses multiple spaces."""
    html = "<p>Text   with    extra   spaces.</p>"
    options = ConversionOptions(whitespace_mode=WhitespaceMode("Normalized"))

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Text" in result.content
    assert result.content is not None
    assert "with" in result.content
    assert result.content is not None
    assert "extra" in result.content
    assert result.content is not None
    assert "spaces." in result.content


def test_options_whitespace_strict() -> None:
    """Strict whitespace mode preserves whitespace as-is."""
    html = "<p>Preserved   spacing.</p>"
    options = ConversionOptions(whitespace_mode=WhitespaceMode("Strict"))

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "Preserved" in result.content
    assert result.content is not None
    assert "spacing." in result.content


def test_options_wrap_disabled() -> None:
    """Wrap option disabled preserves long lines without breaking."""
    html = "<p>This is a long paragraph that should not be wrapped at all because wrapping is disabled.</p>"
    options = ConversionOptions(wrap=False)

    result = convert(html, options)
    assert result.content is not None
    assert "This is a long paragraph that should not be wrapped at all because wrapping is disabled." in result.content


def test_options_wrap_enabled() -> None:
    """Wrap option enabled with custom width wraps long lines."""
    html = "<p>This is a long paragraph that should be wrapped at the specified column width when the wrap option is enabled.</p>"
    options = ConversionOptions(wrap=True, wrap_width=40)

    result = convert(html, options)
    assert result.content is not None and (not hasattr(result.content, "__len__") or len(result.content) > 0)
    assert result.content is not None
    assert "This is a long paragraph" in result.content
